const $=id=>document.getElementById(id),copy=x=>JSON.parse(JSON.stringify(x)),api={music:window.quantumLab,studio:window.quantumStudio},get=b=>b==='music'?api.music.getSession().config:api.studio.getConfiguration(),history={},previousPreset={music:null,studio:null};let applying=false,gesture=null;
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;');
function focusControl(id){const el=$(id);if(!el)return;for(let p=el.parentElement;p;p=p.parentElement)if(p.tagName==='DETAILS')p.open=true;el.scrollIntoView?.({block:'center',behavior:'instant'});el.focus({preventScroll:true});}
function drawPipeline(b){const host=$(b+'-pipeline'),c=get(b),steps=pipeline(b,c);host.style.gridTemplateColumns=`38px repeat(${steps.length},minmax(90px,1fr))`;host.innerHTML='<span></span>'+steps.map(s=>'<span class="pipeline-heading">'+esc(s.label)+'</span>').join('');for(let q=0;q<2;q++)host.insertAdjacentHTML('beforeend',`<strong class="pipeline-wire">q${q}</strong>`+steps.map(s=>{const v=s.cells[q],attrs=v.focus?` data-focus-control="${esc(v.focus)}"`:v.gate!==undefined?` data-inspect-gate="${v.gate}"`:v.slot!==undefined?` data-inspect-slot="${v.slot}" data-wire="${v.wire}"`:'';return `<${attrs?'button':'span'} class="pipeline-cell ${v.kind||''}"${attrs}${v.kind==='slider'?' title="Controlled by a preparation slider or switch"':''}>${esc(v.text)}</${attrs?'button':'span'}>`;}).join(''));}
function redraw(b){const h=history[b];$(b+'-undo').disabled=!h.canUndo;$(b+'-redo').disabled=!h.canRedo;$(b+'-history-status').textContent=h.canUndo?'Undo: '+h.past.at(-1).label:'No earlier configuration';$(b+'-preset-return').disabled=!previousPreset[b];for(const id of b==='music'?['m-gate-undo']:['s-undo'])if($(id))$(id).disabled=!h.canUndo;drawPipeline(b);}
function observe(b,label='Configuration edit'){if(applying)return;history[b].observe(get(b),label);redraw(b);}
function finish(){if(!gesture)return;const b=gesture.b;gesture=null;history[b].end(get(b));redraw(b);}
function restore(b,c){applying=true;try{if(b==='music')api.music.restore(JSON.stringify({application:'Pundora Quantum Music Studio',version:2,config:c}));else api.studio.setConfiguration(c);}finally{applying=false;redraw(b);}}
function undo(b,redo=false){finish();if(history[b].transaction)history[b].end(get(b));const c=redo?history[b].redo():history[b].undo();if(c)restore(b,c);}
function loadPreset(b,id){const before=get(b),p=presetInfo(b,id);if(!p)throw Error('Unknown preset');previousPreset[b]=copy(before);const owns=history[b].begin('Load '+p.label);if(b==='music')api.music.edit(applyPreset(b,before,id));else api.studio.setConfiguration(applyPreset(b,before,id));if(owns)history[b].end(get(b));redraw(b);$(b+'-preset-note').textContent='Loaded '+p.label+'. Return before preset restores the previous complete configuration.';}
for(const b of ['music','studio']){history[b]=new EditHistory(get(b));const root=$(b+'-workbench'),transport=document.querySelector(b==='music'?'#music-workbench .transport':'.studio-transport'),row=document.createElement('div');row.className='history-tools';row.innerHTML=`<button id="${b}-undo" data-history="undo" class="secondary-button">Undo</button><button id="${b}-redo" data-history="redo" class="secondary-button">Redo</button><span id="${b}-history-status" role="status"></span>`;transport.append(row);$(b+'-undo').onclick=()=>undo(b);$(b+'-redo').onclick=()=>undo(b,true);
 const library=document.createElement('details');library.id=b+'-preset-library';library.className='preset-library';library.innerHTML=`<summary>Example library · preparation, circuits & instruments</summary><div class="preset-library-body"><label>Example <select id="${b}-preset-select"></select></label><p id="${b}-preset-replaces"></p><div class="studio-buttons"><button id="${b}-preset-apply" class="play-button">Load selected example</button><button id="${b}-preset-return" data-history="return" class="secondary-button">Return before preset</button></div><p id="${b}-preset-note" role="status">Loading is explicit. A previous snapshot is kept. Undo/Redo and snapshots are temporary for this page load.</p></div>`;const anchor=root.querySelector(b==='music'?'.workspace':'.studio-layout');anchor.before(library);const list=b==='music'?MUSIC_PRESETS:STUDIO_PRESETS;for(const p of list){const option=document.createElement('option');option.value=p.id;option.textContent=p.label;$(b+'-preset-select').append(option);}const summary=()=>$(b+'-preset-replaces').textContent='Replaces: '+presetInfo(b,$(b+'-preset-select').value).fields.join(', ')+'. Other settings stay as selected.';$(b+'-preset-select').onchange=summary;summary();$(b+'-preset-apply').onclick=()=>loadPreset(b,$(b+'-preset-select').value);$(b+'-preset-return').onclick=()=>{if(!previousPreset[b])return;const next=copy(previousPreset[b]);previousPreset[b]=null;history[b].begin('Return before preset');restore(b,next);history[b].end(get(b));redraw(b);};
 const panel=document.createElement('div');panel.className='integrated-pipeline';panel.innerHTML=`<h3>Complete preparation → operations → readout</h3><p>Preparation controls are marked in purple. Click them to focus the matching slider. Added gates keep their order; selecting one opens inspection.</p><div class="pipeline-scroll"><div id="${b}-pipeline" class="pipeline-grid" role="group" aria-label="Complete two-qubit pipeline"></div></div>`;if(b==='music')document.querySelector('.state-panel .coupling').after(panel);else $('nmr-prepare-panel').querySelector('.qubit-studio-grid').before(panel);
 panel.addEventListener('click',e=>{const bt=e.target.closest('button');if(!bt)return;if(bt.dataset.focusControl)focusControl(bt.dataset.focusControl);else if(bt.dataset.inspectGate!==undefined){const old=document.querySelector(`#m-circuit [data-m-step="${bt.dataset.inspectGate}"]`);old?.click();focusControl('m-gate-inspector');}else if(bt.dataset.inspectSlot!==undefined){document.querySelector(`#s-circuit [data-step="${bt.dataset.inspectSlot}"][data-q="${bt.dataset.wire}"]`)?.click();focusControl('s-gate-editor');}});
 root.addEventListener('pointerdown',e=>{const t=e.target;if(t.matches('input[type=range]')&&t.id!=='s-cursor'){finish();history[b].begin('Change '+(t.labels?.[0]?.textContent.trim()||t.id));gesture={b,target:t};}},true);
 root.addEventListener('keydown',e=>{if(e.target.matches('input[type=range]')&&['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End','PageUp','PageDown'].includes(e.key)&&e.target.id!=='s-cursor'){if(!gesture){history[b].begin('Change '+(e.target.labels?.[0]?.textContent.trim()||e.target.id));gesture={b,target:e.target};}}},true);
 for(const type of ['input','change','click'])root.addEventListener(type,e=>{if(applying||gesture||e.target.closest('[data-history],.history-tools,.pipeline-grid'))return;const label=type==='click'?'Action: '+(e.target.closest('button')?.textContent.trim().slice(0,55)||'edit'):'Change '+(e.target.labels?.[0]?.textContent.trim().slice(0,55)||e.target.id||'setting');const owns=history[b].begin(label);queueMicrotask(()=>{if(owns&&!gesture){history[b].end(get(b));redraw(b);}});},true);
 document.addEventListener(b+':configuration',()=>observe(b));redraw(b);
}
for(const type of ['pointerup','pointercancel','keyup'])document.addEventListener(type,()=>queueMicrotask(finish),true);document.addEventListener('focusout',e=>{if(gesture?.target===e.target)finish();},true);window.addEventListener('blur',finish);
// Programmatic edits and asynchronous imports share the same configuration history.
for(const [b,methods] of [['music',['edit','restore']],['studio',['setConfiguration','placeGate']]])for(const name of methods){const original=api[b][name];api[b][name]=function(...args){const owns=!applying&&history[b].begin(name==='restore'?'Restore / import session':'Configuration edit');const value=original.apply(this,args);if(!applying){if(owns)history[b].end(get(b));else history[b].observe(get(b));redraw(b);}return value;};}
for(const [id,b] of [['m-gate-undo','music'],['s-undo','studio']])$(id).addEventListener('click',e=>{e.preventDefault();e.stopImmediatePropagation();undo(b);},true);
