const shortcuts=[...document.querySelectorAll('[data-preset]')].map(bt=>[bt,'music',bt.dataset.preset]).concat([...document.querySelectorAll('[data-music-lesson]')].map(bt=>[bt,'music',bt.dataset.musicLesson==='bell'?'gate-bell':bt.dataset.musicLesson]),[...document.querySelectorAll('[data-molecule]')].map(bt=>[bt,'studio','molecule-'+bt.dataset.molecule]),[['m-clean-preset','music','clean-sine'],['s-strike','studio','single'],['s-chord','studio','both'],['s-bell','studio','bell'],['s-echo-demo','studio','echo']].map(([id,b,p])=>[$(id),b,p]));
