document.body.classList.add('p5-enabled');window.quantumHistory={loadPreset,undo:b=>undo(b),redo:b=>undo(b,true),getState:b=>({current:copy(history[b].current),undoCount:history[b].past.length,redoCount:history[b].future.length}),finishGesture:finish};
